import XCTest

final class OpenBobDMTests: XCTestCase {
    func testOpenBobDM() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.launch()

        let gotIt = app.buttons["Got it"]

        if !app.navigationBars["Bob"].waitForExistence(timeout: 20) {
            let bobCell = app.cells.containing(.staticText, identifier: "Bob").firstMatch
            XCTAssertTrue(bobCell.waitForExistence(timeout: 60), "Bob chat row did not appear")
            bobCell.tap()
        }

        if gotIt.waitForExistence(timeout: 10) {
            gotIt.tap()
        }

        XCTAssertTrue(app.navigationBars["Bob"].waitForExistence(timeout: 30), "DM conversation with Bob did not open")
    }
}
